/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METPrintMgmtNode_Sales_Extension</c> populates custom doc type
/// </summary>
[ExtensionOf(classStr(PrintMgmtNode_Sales))]
final class METPrintMgmtNode_Sales_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// Gets a list of valid document types for the node. A list of valid document types 
    /// for the node. The results can vary based on what is configured in the application
    /// because configuration keys are used to determine this list.
    /// </summary>
    /// <returns>list </returns>
    public List getDocumentTypes()
    {
        List ret = next getDocumentTypes();

        ret.addEnd(PrintMgmtDocumentType::METCustActivityStatement);
        
        //MPJ_15231_Customer Statement DCP 29/03/2022
        ret.addEnd(PrintMgmtDocumentType::METCustActivityStatementMulti);

        //CB730_SalesOutboundDocumentation
        ret.addEnd(PrintMgmtDocumentType::METSOLoadPlanningAid);
        ret.addEnd(PrintMgmtDocumentType::METSOLoadPlanningReport);
        ret.addEnd(PrintMgmtDocumentType::METSOCoverNotes);
        ret.addEnd(PrintMgmtDocumentType::METSODangerousManifest);
        ret.addEnd(PrintMgmtDocumentType::METSOContinuingPermissionNote);
        ret.addEnd(PrintMgmtDocumentType::METPickupAdvice);
        ret.addEnd(PrintMgmtDocumentType::METSOMultimodalDangerousGoods);
        ret.addEnd(PrintMgmtDocumentType::METTOContinuingPermissionNote);
        //ret.addEnd(PrintMgmtDocumentType::METContainerContentReport); // commented based on CB231_ContainerContentReport
        //CB730_SalesOutboundDocumentation

        return ret;
    }
